"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import { useForm, useWatch } from "react-hook-form";
import * as z from "zod";
import { useState, useTransition } from "react";
import { format } from "date-fns";

import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Checkbox } from "@/components/ui/checkbox";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { findSacramentDateAction } from "./actions";
import type { FindSacramentDateOutput } from "@/ai/flows/sacrament-date-finder";
import { Label } from "@/components/ui/label";

import {
  User,
  CalendarDays,
  Home,
  Phone,
  Users,
  HeartHandshake,
  Sparkles,
  Loader2,
  MapPin,
} from "lucide-react";
import { CrossIcon, DoveIcon, ChaliceIcon } from "@/components/icons";


const participantSchema = z.object({
  fullName: z.string().min(3, "Full name must be at least 3 characters."),
  dob: z.date({ required_error: "Date of birth is required." }),
  address: z.string().min(5, "Address is required."),
  phone: z.string().min(7, "A valid phone number is required."),
  maritalStatus: z.enum(["Single", "Divorced", "Widowed"], {
    required_error: "Marital status is required.",
  }),
  sacraments: z.object({
    baptism: z.boolean().default(false),
    baptismDate: z.string().optional(),
    firstCommunion: z.boolean().default(false),
    firstCommunionDate: z.string().optional(),
    confirmation: z.boolean().default(false),
    confirmationDate: z.string().optional(),
  }),
});

const formSchema = z.object({
  participant1: participantSchema,
  participant2: participantSchema,
  timeTogether: z.string().min(1, "This field is required."),
  liveTogether: z.enum(["Yes", "No"], { required_error: "Please select an option." }),
  weddingDate: z.date().optional(),
});

type FormValues = z.infer<typeof formSchema>;
type ParticipantKey = "participant1" | "participant2";
type SacramentType = "Baptism" | "First Communion" | "Confirmation";

type SacramentFinderState = {
  open: boolean;
  participantKey: ParticipantKey | null;
  sacramentType: SacramentType | null;
  participantName: string;
};

function SacramentFinderDialog({
  state,
  onClose,
  onDateFound,
}: {
  state: SacramentFinderState;
  onClose: () => void;
  onDateFound: (result: FindSacramentDateOutput) => void;
}) {
  const [isPending, startTransition] = useTransition();
  const { toast } = useToast();

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const approximateYear = formData.get("approximateYear") as string;
    const location = formData.get("location") as string;

    if (!state.participantKey || !state.sacramentType || !state.participantName) return;

    startTransition(async () => {
      try {
        const result = await findSacramentDateAction({
          name: state.participantName,
          sacramentType: state.sacramentType,
          approximateYear,
          location,
        });
        onDateFound(result);
        toast({
          title: "Date Found!",
          description: `We've found a date for ${state.sacramentType} with ${result.confidenceLevel * 100}% confidence.`,
        });
        onClose();
      } catch (error) {
        toast({
          variant: "destructive",
          title: "Error",
          description: "Could not find the sacrament date. Please try again.",
        });
      }
    });
  };

  return (
    <Dialog open={state.open} onOpenChange={onClose}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="font-headline">
            Find Sacrament Date: {state.sacramentType}
          </DialogTitle>
          <DialogDescription>
            Provide details for {state.participantName} to help us find the exact date.
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="approximateYear">Approximate Year</Label>
            <Input
              id="approximateYear"
              name="approximateYear"
              placeholder="e.g., 1995"
              required
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="location">Location (Church, City)</Label>
            <Input
              id="location"
              name="location"
              placeholder="e.g., St. Peter's, Rome"
              required
            />
          </div>
          <DialogFooter>
            <Button type="button" variant="ghost" onClick={onClose} disabled={isPending}>
              Cancel
            </Button>
            <Button type="submit" disabled={isPending}>
              {isPending ? <Loader2 className="animate-spin" /> : "Find Date"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}


function ParticipantCard({
  participantKey,
  title,
  form,
  onFindSacrament,
}: {
  participantKey: ParticipantKey;
  title: string;
  form: any;
  onFindSacrament: (
    participantKey: ParticipantKey,
    sacramentType: SacramentType
  ) => void;
}) {

  const watchedSacraments = useWatch({
    control: form.control,
    name: `${participantKey}.sacraments`
  });

  const sacramentFields: {
    key: "baptism" | "firstCommunion" | "confirmation";
    label: SacramentType;
    Icon: React.ElementType;
  }[] = [
    { key: "baptism", label: "Baptism", Icon: CrossIcon },
    { key: "firstCommunion", label: "First Communion", Icon: ChaliceIcon },
    { key: "confirmation", label: "Confirmation", Icon: DoveIcon },
  ];

  return (
    <Card className="overflow-hidden">
      <CardHeader>
        <CardTitle className="font-headline text-2xl flex items-center gap-2">
          <User /> {title}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <FormField
            control={form.control}
            name={`${participantKey}.fullName`}
            render={({ field }) => (
              <FormItem>
                <FormLabel>Full Name</FormLabel>
                <FormControl>
                  <Input placeholder="John Doe" {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name={`${participantKey}.dob`}
            render={({ field }) => (
              <FormItem className="flex flex-col">
                <FormLabel>Date of Birth</FormLabel>
                <Popover>
                  <PopoverTrigger asChild>
                    <FormControl>
                      <Button
                        variant={"outline"}
                        className={cn(
                          "w-full pl-3 text-left font-normal",
                          !field.value && "text-muted-foreground"
                        )}
                      >
                        {field.value ? (
                          format(field.value, "PPP")
                        ) : (
                          <span>Pick a date</span>
                        )}
                        <CalendarDays className="ml-auto h-4 w-4 opacity-50" />
                      </Button>
                    </FormControl>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="start">
                    <Calendar
                      mode="single"
                      selected={field.value}
                      onSelect={field.onChange}
                      disabled={(date) =>
                        date > new Date() || date < new Date("1900-01-01")
                      }
                      initialFocus
                    />
                  </PopoverContent>
                </Popover>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name={`${participantKey}.address`}
            render={({ field }) => (
              <FormItem>
                <FormLabel>Address</FormLabel>
                <FormControl>
                  <Input placeholder="123 Main St, Anytown" {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name={`${participantKey}.phone`}
            render={({ field }) => (
              <FormItem>
                <FormLabel>Phone Number</FormLabel>
                <FormControl>
                  <Input placeholder="(555) 123-4567" {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name={`${participantKey}.maritalStatus`}
            render={({ field }) => (
              <FormItem>
                <FormLabel>Marital Status</FormLabel>
                <Select
                  onValueChange={field.onChange}
                  defaultValue={field.value}
                >
                  <FormControl>
                    <SelectTrigger>
                      <SelectValue placeholder="Select marital status" />
                    </SelectTrigger>
                  </FormControl>
                  <SelectContent>
                    <SelectItem value="Single">Single</SelectItem>
                    <SelectItem value="Divorced">Divorced</SelectItem>
                    <SelectItem value="Widowed">Widowed</SelectItem>
                  </SelectContent>
                </Select>
                <FormMessage />
              </FormItem>
            )}
          />
        </div>
        <div className="space-y-4 pt-4 border-t">
          <h3 className="text-lg font-semibold font-headline">Sacramental History</h3>
          {sacramentFields.map(({ key, label, Icon }) => (
             <FormField
              key={key}
              control={form.control}
              name={`${participantKey}.sacraments.${key}`}
              render={({ field }) => (
                <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-md border p-4">
                  <FormControl>
                    <Checkbox
                      checked={field.value}
                      onCheckedChange={field.onChange}
                    />
                  </FormControl>
                  <div className="space-y-1 leading-none w-full">
                    <FormLabel className="flex items-center gap-2">
                      <Icon className="h-5 w-5" /> {label} Received
                    </FormLabel>
                    {watchedSacraments?.[key] && (
                        <div className="flex items-center gap-2 pt-2">
                            <Input
                                disabled
                                value={form.getValues(`${participantKey}.sacraments.${key}Date`) || "No date set"}
                                className="flex-grow"
                            />
                            <Button
                                type="button"
                                size="sm"
                                variant="outline"
                                onClick={() => onFindSacrament(participantKey, label)}
                            >
                                <Sparkles className="mr-2 h-4 w-4" /> Find Date
                            </Button>
                        </div>
                    )}
                  </div>
                </FormItem>
              )}
            />
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

export default function EnrollmentForm() {
  const { toast } = useToast();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [dialogState, setDialogState] = useState<SacramentFinderState>({
    open: false,
    participantKey: null,
    sacramentType: null,
    participantName: "",
  });

  const form = useForm<FormValues>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      participant1: {
        fullName: "",
        address: "",
        phone: "",
        sacraments: {
          baptism: false,
          firstCommunion: false,
          confirmation: false,
        },
      },
      participant2: {
        fullName: "",
        address: "",
        phone: "",
        sacraments: {
          baptism: false,
          firstCommunion: false,
          confirmation: false,
        },
      },
      timeTogether: "",
    },
  });

  function onSubmit(values: FormValues) {
    setIsSubmitting(true);
    console.log(values);
    // Simulate API call
    setTimeout(() => {
      toast({
        title: "Form Submitted!",
        description: "Your enrollment information has been received.",
      });
      setIsSubmitting(false);
    }, 1500);
  }

  const handleFindSacrament = (
    participantKey: ParticipantKey,
    sacramentType: SacramentType
  ) => {
    const participantName = form.getValues(`${participantKey}.fullName`);
    if (!participantName) {
      toast({
        variant: "destructive",
        title: "Missing Name",
        description: "Please enter the participant's full name first.",
      });
      return;
    }
    setDialogState({
      open: true,
      participantKey,
      sacramentType,
      participantName,
    });
  };

  const handleDateFound = (result: FindSacramentDateOutput) => {
    if (dialogState.participantKey && dialogState.sacramentType) {
        const sacramentKey = dialogState.sacramentType === "Baptism" ? "baptismDate" : dialogState.sacramentType === "First Communion" ? "firstCommunionDate" : "confirmationDate";
        form.setValue(
            `${dialogState.participantKey}.sacraments.${sacramentKey}`,
            result.sacramentDate
        );
    }
  };

  return (
    <>
      <SacramentFinderDialog
        state={dialogState}
        onClose={() => setDialogState((prev) => ({ ...prev, open: false }))}
        onDateFound={handleDateFound}
      />
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-8">
          <div className="space-y-8">
            <ParticipantCard
              participantKey="participant1"
              title="Participant 1"
              form={form}
              onFindSacrament={handleFindSacrament}
            />
            <ParticipantCard
              participantKey="participant2"
              title="Participant 2"
              form={form}
              onFindSacrament={handleFindSacrament}
            />
          </div>

          <Card>
            <CardHeader>
              <CardTitle className="font-headline text-2xl flex items-center gap-2">
                <Users /> Relationship Information
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <FormField
                  control={form.control}
                  name="timeTogether"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>How long have you been together?</FormLabel>
                      <FormControl>
                        <Input placeholder="e.g., 3 years" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="weddingDate"
                  render={({ field }) => (
                    <FormItem className="flex flex-col">
                      <FormLabel>Do you have a wedding date set?</FormLabel>
                       <Popover>
                  <PopoverTrigger asChild>
                    <FormControl>
                      <Button
                        variant={"outline"}
                        className={cn(
                          "w-full pl-3 text-left font-normal",
                          !field.value && "text-muted-foreground"
                        )}
                      >
                        {field.value ? (
                          format(field.value, "PPP")
                        ) : (
                          <span>Pick a date (optional)</span>
                        )}
                        <HeartHandshake className="ml-auto h-4 w-4 opacity-50" />
                      </Button>
                    </FormControl>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="start">
                    <Calendar
                      mode="single"
                      selected={field.value}
                      onSelect={field.onChange}
                      initialFocus
                    />
                  </PopoverContent>
                </Popover>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>

               <FormField
                  control={form.control}
                  name="liveTogether"
                  render={({ field }) => (
                    <FormItem className="space-y-3">
                      <FormLabel>Do you live together?</FormLabel>
                      <FormControl>
                        <RadioGroup
                          onValueChange={field.onChange}
                          defaultValue={field.value}
                          className="flex flex-col space-y-1"
                        >
                          <FormItem className="flex items-center space-x-3 space-y-0">
                            <FormControl>
                              <RadioGroupItem value="Yes" />
                            </FormControl>
                            <FormLabel className="font-normal">
                              Yes
                            </FormLabel>
                          </FormItem>
                          <FormItem className="flex items-center space-x-3 space-y-0">
                            <FormControl>
                              <RadioGroupItem value="No" />
                            </FormControl>
                            <FormLabel className="font-normal">
                              No
                            </FormLabel>
                          </FormItem>
                        </RadioGroup>
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
            </CardContent>
          </Card>

          <div className="flex justify-end">
            <Button type="submit" size="lg" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Submit Enrollment
            </Button>
          </div>
        </form>
      </Form>
    </>
  );
}
